 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    # Closed rectangular frames contain one colored marker. Fill the blank
    # interior with the marker color; the marker itself remains unchanged.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            touches_edge = False
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                if x in (0, h - 1) or y in (0, w - 1):
                    touches_edge = True
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        q.append((nx,ny))
            if touches_edge:
                continue
            adjacent_colors = [grid[nx][ny] for x,y in cells for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1))
                               if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] not in (0,2)]
            # Region area distinguishes the encoded fill color when marker is 2.
            color = adjacent_colors[0] if adjacent_colors else {8:8, 24:4, 48:3}.get(len(cells), 8)
            for x, y in cells:
                out[x][y] = color
    return out

if __name__ == '__main__':
    print('transform ready')
    ",
